android.extraProguardRules:
# WorkManager (pulled in by react-native-maps) bundles Room 2.5, which finds
# WorkDatabase_Impl by reflection; R8 breaks that lookup and the app crashes on launch.
-keep class * extends androidx.room.RoomDatabase { <init>(); }
-keep class androidx.work.impl.WorkDatabase { *; }
-keep class androidx.work.impl.WorkDatabase_Impl { *; }
-keepnames class androidx.room.** { *; }
